 const API_BASE = 'https://pokeapi.co/api/v2';
 const SPRITE_BASE =
   'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon';

 type NamedResource = { name: string; url: string };

 type ListResponse = {
   results: NamedResource[];
 };

 type GenerationResponse = {
   pokemon_species: NamedResource[];
 };

 type TypeResponse = {
   pokemon: { pokemon: NamedResource }[];
 };

 type TypeDamageResponse = {
   damage_relations: {
     double_damage_to: NamedResource[];
     half_damage_to: NamedResource[];
     no_damage_to: NamedResource[];
   };
 };

 type SpeciesResponse = {
   id: number;
   name: string;
   is_legendary: boolean;
   is_mythical: boolean;
   gender_rate: number;
   generation: NamedResource;
   evolution_chain: NamedResource;
   varieties: { is_default: boolean; pokemon: NamedResource }[];
 };

 type PokemonResponse = {
   id: number;
   name: string;
   forms: NamedResource[];
   types: { type: NamedResource }[];
   abilities: { ability: NamedResource }[];
   height: number;
   weight: number;
   base_experience: number | null;
   stats: { base_stat: number; stat: NamedResource }[];
   sprites: {
     front_default: string | null;
     front_shiny: string | null;
     front_female: string | null;
     front_shiny_female?: string | null;
     other?: {
       'official-artwork'?: {
         front_default: string | null;
         front_shiny: string | null;
       };
       home?: {
         front_default: string | null;
         front_shiny: string | null;
         front_female: string | null;
         front_shiny_female?: string | null;
       };
     };
   };
   species: NamedResource;
 };

 type PokemonFormResponse = {
   id: number;
   name: string;
   form_name: string;
   is_default: boolean;
   is_battle_only: boolean;
   is_mega: boolean;
   pokemon: NamedResource;
   sprites: PokemonResponse['sprites'];
 };

 type EvolutionChainLink = {
   species: NamedResource;
   evolution_details: { gender: number | null }[];
   evolves_to: EvolutionChainLink[];
 };

 type EvolutionChainResponse = {
   chain: EvolutionChainLink;
 };

 export type PokemonSummary = {
   id: number;
   name: string;
   generation: number;
   types: string[];
   speciesId?: number;
 };

 export type RegionalForm = {
   id: number;
   name: string;
   label: string;
   spriteUrl: string | null;
   shinySpriteUrl: string | null;
 };

 export type PokemonDetails = {
   id: number;
   name: string;
   speciesId: number;
   types: string[];
   abilities: string[];
   height: number;
   weight: number;
   baseExperience: number | null;
